.ds-arcade { --ds-cover-bg: var(--ds-ground);
  --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-red); --ds-hand-fill2: var(--ds-blue); --ds-hand-muted: var(--ds-blue-soft); --ds-hand-ground: var(--ds-raised); --ds-hand-stroke: 4; --ds-hand-cap: square; --ds-hand-bg: var(--ds-ground);
  --ds-tpl-edge: 4px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 4px solid var(--ds-ink); --ds-tpl-tile-shadow: 4px 4px 0 0 var(--ds-ink); --ds-tag-radius: 0;
  --ds-slide-bg: var(--ds-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-red); --ds-slide-title-fg: var(--ds-on-red); --ds-slide-split-a: var(--ds-positive); --ds-slide-split-a-fg: var(--ds-on-yellow); --ds-slide-split-b: var(--ds-negative); --ds-slide-split-b-fg: var(--ds-on-red);
  --ds-hero-bg: var(--ds-raised); }
.dark .ds-arcade { background-image: repeating-linear-gradient(0deg, rgba(255,255,255,0) 0 3px, rgba(255,255,255,.05) 3px 4px); }
.ds-arcade .ds-section h2, .ds-arcade .ds-cover-name { font-family: var(--font-display); font-weight: 400; text-transform: uppercase; line-height: 1.3; }
.ds-arcade .ds-section h2 { font-size: clamp(18px, 2.4vw, 30px); max-width: 26ch; } .ds-arcade .ds-cover-name { font-size: clamp(26px, 4vw, 48px); color: var(--ds-red); text-shadow: 4px 4px 0 var(--ds-ink); }
.ds-arcade .ds-eyebrow, .ds-arcade .ds-chip, .ds-arcade .t-label { font-family: var(--font-display); font-size: 10px; letter-spacing: .04em; }
.ds-arcade .ds-chip { border-radius: 0; border-width: 2px; } .ds-arcade .ds-comp, .ds-arcade .ds-motif, .ds-arcade .ds-note, .ds-arcade .ds-voice, .ds-arcade .ds-hand-panel, .ds-arcade .ds-swatch-chip { border: 4px solid var(--ds-ink); border-radius: 0; }
.ds-arcade .ds-lede, .ds-arcade .ds-two p, .ds-arcade .ds-three p { font-size: 18px; }
.ds-arcade .ds-hand-art, .ds-arcade .ds-tpl-figure, .ds-arcade .ar-sample { background-image: linear-gradient(45deg, var(--ds-sunk) 25%, transparent 25%, transparent 75%, var(--ds-sunk) 75%), linear-gradient(45deg, var(--ds-sunk) 25%, transparent 25%, transparent 75%, var(--ds-sunk) 75%); background-size: 32px 32px; background-position: 0 0, 16px 16px; }
.ds-arcade .h-num { font-family: var(--font-mono); font-size: 44px; font-weight: 400; letter-spacing: 0; } .ds-arcade .h-text { font-family: var(--font-display); font-size: 8px; letter-spacing: 0; paint-order: stroke; stroke: var(--ds-raised); stroke-width: 3px; }
.ds-arcade .ds-tpl-brand { font-family: var(--font-display); font-size: 14px; color: var(--ds-red); } .ds-arcade .ds-tpl-slide-h, .ds-arcade .ds-tpl-hero-h, .ds-arcade .ds-tpl-ed-h { font-family: var(--font-display); text-transform: uppercase; line-height: 1.35; font-weight: 400; }
.ds-arcade .ds-tpl-slide-h { font-size: 6.5cqw; } .ds-arcade .ds-tpl-hero-h { font-size: clamp(20px, 3vw, 36px); max-width: 16ch; } .ds-arcade .ds-tpl-ed-h { font-size: clamp(16px, 2.2vw, 26px); max-width: 30ch; }
.ds-arcade .ds-tpl-slide-big { font-family: var(--font-mono); font-weight: 400; letter-spacing: 0; } .ds-arcade .ds-tpl-stage-top, .ds-arcade .ds-tpl-stage-foot { font-family: var(--font-display); font-size: 1.8cqw; }
.ds-arcade .ds-tpl-pull-n { font-family: var(--font-mono); color: var(--ds-red); } .ds-arcade .ds-tpl-dropcap { font-family: var(--font-display); font-size: 36px; padding-top: 10px; color: var(--ds-red); }
.ds-arcade .ds-tpl-tag { font-family: var(--font-display); font-size: 9px; border: 0; margin: 4px; box-shadow: var(--ds-pixel-edge); background: var(--ds-raised); }
.ds-arcade .ds-tpl-tag.is-idle { background: var(--ds-sunk); }
.ds-arcade .ds-tpl-stage-title .ds-tpl-stage-foot, .ds-arcade .ds-tpl-stage-title .ds-tpl-stage-top { opacity: 1; }
.ds-arcade .ar-ground { fill: var(--ds-ground); } .ds-arcade .ar-chk { fill: var(--ds-sunk); } .ds-arcade .ar-raised { fill: var(--ds-raised); } .ds-arcade .ar-sunk { fill: var(--ds-sunk); } .ds-arcade .ar-ink { fill: var(--ds-ink); }
.ds-arcade .ar-red { fill: var(--ds-red); } .ds-arcade .ar-blue { fill: var(--ds-blue); } .ds-arcade .ar-yellow { fill: var(--ds-yellow); } .ds-arcade .ar-green { fill: var(--ds-positive); } .ds-arcade .ar-magenta { fill: var(--ds-magenta); } .ds-arcade .ar-cyan { fill: var(--ds-cyan); }
.ds-arcade .ar-heart-off { fill: var(--ds-line); } .ds-arcade .ar-brick { fill: var(--ds-red); } .ds-arcade .ar-brick-hi { fill: var(--ds-magenta); }
.ds-arcade .ar-px-t { font-family: var(--font-display); font-size: 11px; fill: var(--ds-ink); } .ds-arcade .ar-on-ink { fill: var(--ds-ground); } .ds-arcade .ar-yellow-t { fill: var(--ds-yellow); } .ds-arcade .ar-red-t { fill: var(--ds-red); } .ds-arcade .ar-vt { font-family: var(--font-mono); font-size: 26px; fill: var(--ds-ink); }
@keyframes ar-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
.ds-arcade .ar-blink { animation: ar-blink 1s steps(1) infinite; } @media (prefers-reduced-motion: reduce) { .ds-arcade .ar-blink { animation: none; } }
.ds-arcade .ar-btn { font-family: var(--font-display); font-size: 12px; line-height: 16px; padding: 12px 16px; border: 0; margin: 4px 8px 8px 4px; background: var(--ds-raised); color: var(--ds-ink); box-shadow: var(--ds-pixel-shadow); cursor: pointer; text-transform: uppercase; }
.ds-arcade .ar-btn:active { transform: translate(4px, 4px); box-shadow: var(--ds-pixel-edge); } .ds-arcade .ar-btn:focus-visible { outline: 4px solid var(--ds-yellow); outline-offset: 4px; }
.ds-arcade .ar-btn-primary { background: var(--ds-red); color: var(--ds-on-red); } .ds-arcade .ar-btn-coin { background: var(--ds-yellow); color: var(--ds-on-yellow); } .ds-arcade .ar-btn-blue { background: var(--ds-blue); color: var(--ds-on-blue); } .ds-arcade .ar-btn-sm { padding: 8px 12px; font-size: 10px; }
.ds-arcade .ar-tag { display: inline-flex; gap: 6px; padding: 5px 8px; margin: 4px; border: 0; box-shadow: var(--ds-pixel-edge); font-family: var(--font-display); font-size: 9px; text-transform: uppercase; background: var(--ds-raised); color: var(--ds-ink); }
.ds-arcade .ar-tag-coin { background: var(--ds-yellow); color: var(--ds-on-yellow); } .ds-arcade .ar-tag-green { background: var(--ds-positive-soft); color: var(--ds-positive); } .ds-arcade .ar-tag-red { background: var(--ds-negative-soft); color: var(--ds-negative); } .ds-arcade .ar-tag-warn { background: var(--ds-caution-soft); color: var(--ds-caution); } .ds-arcade .ar-tag-magenta { color: var(--ds-magenta); } .ds-arcade .ar-tag-cyan { color: var(--ds-cyan); }
.dark .ds-arcade .ar-tag-cyan, .dark .ds-arcade .ar-tag-magenta { background: var(--ds-sunk); }
.ds-arcade .ar-stat { display: grid; gap: 4px; padding: 12px 16px; border: 4px solid var(--ds-ink); background: var(--ds-raised); min-width: 180px; } .ds-arcade .ar-stat-coin { background: var(--ds-yellow); } .ds-arcade .ar-small { font-size: 14px; color: var(--ds-ink-muted); } .ds-arcade .ar-stat-coin .ar-small { color: var(--ds-on-yellow); } .ds-arcade .ds-stats { gap: 16px; }
.ds-arcade .ar-combo { color: var(--ds-red); text-shadow: 3px 3px 0 var(--ds-ink); margin: 0; } .dark .ds-arcade .ar-combo { text-shadow: 3px 3px 0 var(--ds-blue); }
.ds-arcade .ar-callout { padding: 12px 16px; border: 4px solid var(--ds-ink); font-size: 17px; line-height: 1.4; background: var(--ds-raised); } .ds-arcade .ar-callout strong { font-weight: 700; } .ds-arcade .ar-callout-green { background: var(--ds-positive-soft); } .ds-arcade .ar-callout-warn { background: var(--ds-caution-soft); } .ds-arcade .ar-callout-red { background: var(--ds-negative-soft); }
.ds-arcade .ar-dialog { position: relative; margin: 4px; padding: 14px 40px 14px 16px; box-shadow: var(--ds-pixel-edge); background: var(--ds-raised); } .ds-arcade .ar-dialog p { margin: 6px 0 0; font-family: var(--font-mono); font-size: 22px; line-height: 26px; } .ds-arcade .ar-dialog-who { font-family: var(--font-display); font-size: 10px; color: var(--ds-red); } .ds-arcade .ar-dialog-more { position: absolute; right: 14px; bottom: 10px; font-family: var(--font-display); font-size: 12px; } .ds-arcade .ar-dialog-wide { margin: 32px 4px 4px; }
.ds-arcade .ar-panel { border: 4px solid var(--ds-ink); background: var(--ds-raised); padding: 16px; display: grid; gap: 10px; min-width: 0; position: relative; } .ds-arcade .ar-panel-active { box-shadow: 8px 8px 0 0 var(--ds-ink); } .ds-arcade .ar-panel h3 { margin: 0; } .ds-arcade .ar-card-p { margin: 0; line-height: 1.45; color: var(--ds-ink-muted); } .ds-arcade .ar-panel > .t-label { display: block; }
.ds-arcade .ar-ribbon { display: inline-block; justify-self: start; font-family: var(--font-display); font-size: 10px; line-height: 16px; padding: 6px 12px; background: var(--ds-yellow); color: var(--ds-on-yellow); margin: 4px 4px 8px; box-shadow: var(--ds-pixel-edge); } .ds-arcade .ar-ribbon-green { background: var(--ds-positive); color: var(--ds-on-red); }
.ds-arcade .ar-hud { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center; padding: 8px 12px; background: var(--ds-ink); color: var(--ds-ground); } .ds-arcade .ar-hud .t-label { color: var(--ds-yellow); } .ds-arcade .ar-hud-score { font-family: var(--font-mono); font-size: 26px; line-height: 24px; color: var(--ds-ground); } .ds-arcade .ar-dim { opacity: .6; } .ds-arcade .ar-hud-end { margin-left: auto; }
.dark .ds-arcade .ar-hud { background: var(--ds-sunk); color: var(--ds-ink); box-shadow: inset 0 0 0 2px var(--ds-line); } .dark .ds-arcade .ar-hud-score { color: var(--ds-ink); }
.ds-arcade .ar-hearts { display: inline-flex; gap: 6px; } .ds-arcade .ar-hearts i { display: inline-block; width: 18px; height: 16px; background: var(--ds-red); clip-path: polygon(14% 0, 43% 0, 43% 14%, 57% 14%, 57% 0, 86% 0, 86% 14%, 100% 14%, 100% 43%, 86% 43%, 86% 57%, 71% 57%, 71% 71%, 57% 71%, 57% 86%, 43% 86%, 43% 71%, 29% 71%, 29% 57%, 14% 57%, 14% 43%, 0 43%, 0 14%, 14% 14%); } .ds-arcade .ar-hearts .ar-heart-off-i { background: var(--ds-ink-muted); opacity: .5; }
.ds-arcade .ar-hp { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; } .ds-arcade .ar-blocks { display: inline-flex; gap: 4px; padding: 4px; background: var(--ds-ink); } .ds-arcade .ar-blocks i { display: block; width: 14px; height: 14px; background: var(--ds-sunk); } .ds-arcade .ar-blocks .ar-b-on { background: var(--ds-positive); } .ds-arcade .ar-hp-n { color: var(--ds-ink); }
.ds-arcade .ar-hp-lg { margin-top: 24px; } .ds-arcade .ar-hp-lg .ar-blocks i { width: 20px; height: 20px; }
.ds-arcade .ar-coins { display: inline-flex; gap: 6px; } .ds-arcade .ar-coin-i { display: inline-block; width: 16px; height: 16px; background: var(--ds-yellow); box-shadow: inset 0 0 0 2px var(--ds-ink); } .ds-arcade .ar-coin-off-i { background: transparent; }
.ds-arcade .ar-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; } .ds-arcade .ar-cta { justify-content: flex-start; margin-top: 24px; gap: 16px; } .ds-arcade .ar-press { color: var(--ds-red); }
.ds-arcade .ar-sample { background-color: var(--ds-ground); padding: 0 20px 48px; border-top: 4px solid var(--ds-ink); border-bottom: 4px solid var(--ds-ink); }
.ds-arcade .ar-sample-in { max-width: 1140px; margin: 0 auto; } .ds-arcade .ar-hud-top { margin: 0 -20px; padding: 12px 20px; }
.ds-arcade .ar-sample-grid { display: grid; gap: 32px; margin-top: 32px; align-items: center; } .ds-arcade .ar-sample-h { margin: 8px 0 0; color: var(--ds-red); text-shadow: 4px 4px 0 var(--ds-ink); } .ds-arcade .ar-sample-lede { margin-top: 16px; max-width: 46ch; } .ds-arcade .ar-sample .ar-combo { margin-top: 20px; }
.ds-arcade .ar-sample-fig svg { display: block; width: 100%; max-width: 320px; height: auto; margin: 0 auto; border: 4px solid var(--ds-ink); background: var(--ds-raised); box-shadow: 8px 8px 0 0 var(--ds-ink); }
.ds-arcade .ar-sample-bottom { display: grid; gap: 24px; margin-top: 32px; } .ds-arcade .ar-foot { margin: 20px 0 0; text-align: center; color: var(--ds-ink-muted); }
@container (min-width: 760px) { .ds-arcade .ar-sample { padding: 0 40px 64px; } .ds-arcade .ar-hud-top { margin: 0 -40px; padding: 12px 40px; } .ds-arcade .ar-sample-grid { grid-template-columns: 3fr 2fr; } .ds-arcade .ar-sample-bottom { grid-template-columns: 1fr 1fr; } }
